        return
    except json.JSONDecodeError:
        self._send_invalid("请求体不是合法 JSON")
        return

    try:
        valid, reason = (
            store.verify_trust_credential_with_status(tenant, data)
        )
    except Exception:  # noqa: BLE001 验签失败绝不暴露内部细节
